const input = $('Webhook').first().json;
const clause = input.body || input;

if (!clause.clause_text) {
  throw new Error('clause_text is required');
}

return [{
  json: {
    clause_instance_id: clause.clause_instance_id || 'unknown',
    clause_id: clause.clause_id || 'unknown',
    clause_text: clause.clause_text,
    run_id: clause.run_id || '',
    document_id: clause.document_id || '',
    blueprint_version_id: clause.blueprint_version_id || null,
    matter_policy_id: clause.matter_policy_id || null,
    contract_type: clause.contract_type || 'nueva_planta',
    started_at: new Date().toISOString()
  }
}];

const prevData = $('Keyword Router').first().json;
const keywordRouter = prevData._keyword_router;
let routerOutput = { route: 'OtherUnknown', confidence: 0, reasoning: '' };

// Check if keyword routing succeeded with high confidence
if (keywordRouter?.routed && keywordRouter.confidence >= 0.65) {
  routerOutput = {
    route: keywordRouter.family,
    confidence: keywordRouter.confidence,
    reasoning: 'Keyword pattern match: ' + keywordRouter.method + ' (' + keywordRouter.matched_patterns + ' patterns)'
  };
} else {
  // Use LLM result
  try {
    const content = $('Router Agent').first().json?.choices?.[0]?.message?.content || '{}';
    const parsed = JSON.parse(content);
    routerOutput = {
      route: parsed.route || 'OtherUnknown',
      confidence: parsed.confidence || 0.5,
      reasoning: parsed.reasoning || 'LLM classification'
    };
  } catch (e) {
    // Fallback to keyword result if available
    if (keywordRouter?.family) {
      routerOutput = {
        route: keywordRouter.family,
        confidence: keywordRouter.confidence || 0.5,
        reasoning: 'LLM failed, using keyword fallback'
      };
    } else {
      routerOutput.reasoning = 'Parse error: ' + e.message;
    }
  }
}

// NORMALIZE: Map various formats to canonical PascalCase names
const FAMILY_NORMALIZE = {
  'indemnity_prodco': 'IndemnityProdCo',
  'indemnityprodco': 'IndemnityProdCo',
  'prodco_indemnification': 'IndemnityProdCo',
  'indemnity_amazon': 'IndemnityAmazon',
  'indemnityamazon': 'IndemnityAmazon',
  'amazon_indemnification': 'IndemnityAmazon',
  'defense_settlement': 'IndemnityProcedures',
  'defensesettlement': 'IndemnityProcedures',
  'indemnity_procedures': 'IndemnityProcedures',
  'reps_prodco': 'RepsProdCo',
  'repsprodco': 'RepsProdCo',
  'prodco_representations': 'RepsProdCo',
  'payment_credits': 'PaymentCredits',
  'paymentcredits': 'PaymentCredits',
  'compensation': 'PaymentCredits',
  'fees': 'PaymentCredits',
  'rights_grant': 'RightsGrant',
  'rightsgrant': 'RightsGrant',
  'ownership': 'RightsGrant',
  'rights_reversion': 'RightsReversion',
  'rightsreversion': 'RightsReversion',
  'liability_limitation': 'LiabilityLimitation',
  'liabilitylimitation': 'LiabilityLimitation',
  'limitation_of_liability': 'LiabilityLimitation',
  'termination_rights': 'TerminationRights',
  'terminationrights': 'TerminationRights',
  'termination_consequences': 'TerminationConsequences',
  'terminationconsequences': 'TerminationConsequences',
  'survival_remedies': 'SurvivalRemedies',
  'survivalremedies': 'SurvivalRemedies',
  'survival': 'SurvivalRemedies',
  'services_scope': 'ServicesScope',
  'servicesscope': 'ServicesScope',
  'confidentiality': 'Confidentiality',
  'insurance': 'Insurance',
  'dispute_resolution': 'DisputeResolution',
  'disputeresolution': 'DisputeResolution',
  'other_unknown': 'OtherUnknown',
  'otherunknown': 'OtherUnknown'
};

const rawRoute = (routerOutput.route || 'OtherUnknown').toLowerCase().replace(/[^a-z_]/g, '').trim();
routerOutput.route = FAMILY_NORMALIZE[rawRoute] || routerOutput.route;

// Valid families list
const validFamilies = ['IndemnityProdCo', 'IndemnityAmazon', 'IndemnityProcedures', 'RepsProdCo', 'RepsAmazon', 'RepsTruthTerm', 'PaymentCredits', 'ThirdPartyCredits', 'RightsGrant', 'RightsReversion', 'LiabilityLimitation', 'TerminationRights', 'TerminationConsequences', 'SurvivalRemedies', 'Confidentiality', 'Insurance', 'DisputeResolution', 'ServicesScope', 'OtherUnknown'];
if (!validFamilies.includes(routerOutput.route)) {
  routerOutput.route = 'OtherUnknown';
}

// Include routing metadata
routerOutput._routing_method = keywordRouter?.routed ? 'KEYWORD' : 'LLM';
routerOutput._keyword_confidence = keywordRouter?.confidence || 0;

return [{ json: { ...prevData, routerOutput } }];

const prevData = $('Parse Router').first().json;
let embedding = null;

try {
  embedding = $json.data?.[0]?.embedding || null;
} catch (e) {
  console.log('Embedding parse error:', e.message);
}

return [{ json: { ...prevData, clauseEmbedding: embedding } }];

const prevData = $('Parse Embedding').first().json;
let ragResults = [];

try {
  // Handle both array response and empty response
  const response = $input.first().json;
  if (Array.isArray(response)) {
    ragResults = response;
  } else if (response && typeof response === 'object') {
    // If it's an object with error, treat as empty
    ragResults = [];
  }
} catch (e) {
  console.log('RAG parse error:', e.message);
  ragResults = [];
}

// Group examples by acceptance level
const acceptableExamples = ragResults.filter(r => r.acceptance === 'ACCEPTABLE').slice(0, 2);
const passableExamples = ragResults.filter(r => r.acceptance === 'PASSABLE').slice(0, 2);
const unacceptableExamples = ragResults.filter(r => r.acceptance === 'UNACCEPTABLE').slice(0, 2);

// Format for prompt
const formatExample = (ex) => `[${ex.acceptance}] (similarity: ${(ex.similarity * 100).toFixed(0)}%)\n${ex.example_text.substring(0, 500)}...`;

const ragContext = {
  hasResults: ragResults.length > 0,
  totalFound: ragResults.length,
  acceptableExamples: acceptableExamples.map(formatExample),
  passableExamples: passableExamples.map(formatExample),
  unacceptableExamples: unacceptableExamples.map(formatExample),
  topSimilarity: ragResults[0]?.similarity || 0,
  topAcceptance: ragResults[0]?.acceptance || 'NONE'
};

return [{ json: { ...prevData, ragContext, ragResults } }];

// Get data from Parse RAG Results and Playbook Spec
const prevData = $('Parse RAG Results').first().json;
const family = prevData.routerOutput?.route || 'OtherUnknown';

// Get playbook spec from database response (from Get Playbook Spec node)
let playbookSpec = null;
try {
  const specResponse = $input.all()[0]?.json;
  if (Array.isArray(specResponse) && specResponse.length > 0) {
    playbookSpec = specResponse[0];
  } else if (specResponse && !Array.isArray(specResponse)) {
    playbookSpec = specResponse;
  }
} catch (e) {
  console.log('Playbook spec parse error:', e.message);
}

// Build policySpec from database data or fallback
let policySpec;
if (playbookSpec && playbookSpec.family_id) {
  policySpec = {
    clause_family: playbookSpec.family_id,
    display_name: playbookSpec.display_name,
    priority: playbookSpec.priority,
    requires_legal_review: playbookSpec.requires_legal_review,
    rule_id: `PB:v2026-01:${playbookSpec.family_id}-Core`,
    has_policy_spec: true,
    // Amazon position data
    amazon_position: playbookSpec.amazon_position,
    standard_position: {
      text: playbookSpec.amazon_position?.summary || '',
      summary: playbookSpec.amazon_position?.summary || '',
      core_requirements: playbookSpec.amazon_position?.core_requirements || []
    },
    // Acceptability data
    acceptability_matrix: playbookSpec.acceptability_matrix,
    acceptable_variations: playbookSpec.acceptability_matrix?.acceptable?.required_elements || [],
    unacceptable_patterns: playbookSpec.acceptability_matrix?.unacceptable?.patterns || [],
    passable_variations: playbookSpec.acceptability_matrix?.passable?.variations || [],
    // Negotiation and risk
    negotiation_guidance: playbookSpec.negotiation_guidance,
    risk_assessment: playbookSpec.risk_assessment,
    detection_patterns: playbookSpec.detection_patterns,
    // Policies
    analysis_mode: 'MODE_ENUMERATED_DEVIATIONS',
    required: true,
    routing_policy: {
      type: playbookSpec.priority === 'CRITICAL' ? 'ESCALATE_IF_UNACCEPTABLE' : 'LOG_ONLY',
      block_export: playbookSpec.priority === 'CRITICAL'
    },
    decision_policy: {
      anchor_conf_threshold: 0.85,
      gating_logic: 'STANDARD',
      block_export_if_escalated: playbookSpec.priority === 'CRITICAL'
    }
  };
} else {
  // Fallback for families without playbook spec
  policySpec = {
    id: null,
    rule_id: `default:${family}`,
    clause_family: family,
    required: true,
    analysis_mode: 'MODE_ENUMERATED_DEVIATIONS',
    standard_position: { text: 'Not defined', summary: 'Manual review required' },
    acceptable_variations: [],
    unacceptable_patterns: [],
    routing_policy: { type: 'ESCALATE', block_export: true },
    decision_policy: { anchor_conf_threshold: 0.85, gating_logic: 'STANDARD', block_export_if_escalated: true },
    has_policy_spec: false
  };
}

const TH_ANCHOR = policySpec.decision_policy?.anchor_conf_threshold || 0.85;
const TH_CONF = 0.80;

return [{ json: { ...prevData, policySpec, playbookSpec, TH_ANCHOR, TH_CONF } }];

const data = $('Enrich Policy').first().json;
const family = data.policySpec?.clause_family || 'OtherUnknown';
const clauseText = data.clause_text;
const policySpec = data.policySpec || {};
const playbookSpec = data.playbookSpec;

// Build dynamic prompt from playbook spec data
let paranoidSystem, valuatorSystem, TH_ANCHOR;

if (playbookSpec && playbookSpec.amazon_position) {
  // Dynamic prompt from database playbook spec
  const pos = playbookSpec.amazon_position;
  const matrix = playbookSpec.acceptability_matrix || {};
  const detection = playbookSpec.detection_patterns || {};
  const risk = playbookSpec.risk_assessment || {};

  paranoidSystem = `Eres el Agente Analista Paranoico especializado en cláusulas de ${playbookSpec.display_name}.\n\n` +
    `POSICIÓN ESTÁNDAR DE AMAZON:\n${pos.summary || ''}\n\n` +
    `REQUISITOS CORE:\n${(pos.core_requirements || []).map(r => '- ' + r).join('\n')}\n\n` +
    `PATRONES ACEPTABLES (ejemplo):\n${matrix.acceptable?.example || 'N/A'}\n\n` +
    `VARIACIONES PASABLES (requieren aprobación):\n${(matrix.passable?.variations || []).map(v => '- ' + v).join('\n')}\n\n` +
    `PATRONES INACEPTABLES (CRÍTICOS):\n${(matrix.unacceptable?.patterns || []).map(p => '- ' + p).join('\n')}\n\n` +
    (detection.must_have ? `ANCLAS OBLIGATORIAS (must_have):\n${detection.must_have.map(a => '- \"' + a + '\"').join('\n')}\n\n` : '') +
    (detection.red_flags ? `RED FLAGS:\n${detection.red_flags.map(f => '- \"' + f + '\"').join('\n')}\n\n` : '') +
    `TRIGGERS DE ESCALACIÓN:\n${(risk.escalation_triggers || []).map(t => '- ' + t).join('\n')}\n\n` +
    `Responde SOLO en JSON con observations[], summary, risk_level.`;

  valuatorSystem = `Valuator para ${playbookSpec.display_name}.\n` +
    `analysis_mode = MODE_ENUMERATED_DEVIATIONS.\n` +
    `Prioridad: ${playbookSpec.priority || 'MEDIUM'}.\n` +
    `Requiere revisión legal: ${playbookSpec.requires_legal_review ? 'SÍ' : 'NO'}.\n\n` +
    `Patrones inaceptables detectados = UnacceptableDeviation.\n` +
    `Responde SOLO en JSON con final_status, proposed_changes[], confidence_overall.`;

  TH_ANCHOR = playbookSpec.priority === 'CRITICAL' ? 0.86 : 0.85;

} else {
  // Fallback for unknown families
  paranoidSystem = `Cláusula de la familia ${family} - NO CUBIERTA por Playbook.\n\n` +
    `Analiza el texto buscando:\n1. Obligaciones de las partes\n2. Plazos y condiciones\n3. Exclusiones y limitaciones\n4. Cláusulas de escape o penalización\n\n` +
    `Reporta: observations[], possible_family, risk_indicators.`;

  valuatorSystem = `final_status = NotCoveredByPlaybook.\ndecision = ESCALATE_HUMAN.\nblock_export = true.`;
  TH_ANCHOR = 0.85;
}

// Build user message for Paranoid with enriched data
const paranoidUserMessage = `TEXTO DE LA CLÁUSULA A ANALIZAR:\n${clauseText}\n\n` +
  `POSICIÓN ESTÁNDAR DEL PLAYBOOK:\n${JSON.stringify(policySpec.standard_position || {})}\n\n` +
  `ELEMENTOS REQUERIDOS (ACEPTABLE):\n${JSON.stringify(policySpec.acceptable_variations || [])}\n\n` +
  `PATRONES INACEPTABLES:\n${JSON.stringify(policySpec.unacceptable_patterns || [])}\n\n` +
  `Analiza exhaustivamente y reporta TODAS las desviaciones con offsets exactos.`;

// Build complete messages for OpenAI
const paranoidMessages = [
  { role: 'system', content: paranoidSystem },
  { role: 'user', content: paranoidUserMessage }
];

return [{ json: { 
  ...data, 
  paranoidMessages,
  paranoidSystemPrompt: paranoidSystem,
  valuatorSystemPrompt: valuatorSystem,
  TH_ANCHOR: TH_ANCHOR,
  usedDynamicPrompt: !!playbookSpec
}}];

const prevData = $('Build Family Prompt').first().json;
let paranoidOutput = { observations: [], summary: { counts: { total: 0 }, coverage_confidence: 0 }, risk_level: 'GREEN' };
let validationErrors = [];

try {
  const content = $json.choices?.[0]?.message?.content || '{}';
  const parsed = JSON.parse(content);

  // SCHEMA VALIDATION (Gap 2 - P1)
  // Handle both old format (evidence_spans) and new format (observations)
  if (parsed.evidence_spans && !parsed.observations) {
    parsed.observations = parsed.evidence_spans.map(e => ({
      evidence: e.quote,
      offsets: { start: 0, end: 0 },
      change_type: 'modified',
      possible_category: e.severity === 'high' ? 'MatchesUnacceptable' : 'UnknownChange',
      confidence: 0.8
    }));
  }

  if (!parsed.observations || !Array.isArray(parsed.observations)) {
    validationErrors.push('Missing observations array');
    parsed.observations = [];
  }

  // Validate each observation has required fields
  for (let i = 0; i < parsed.observations.length; i++) {
    const obs = parsed.observations[i];
    if (!obs.offsets || typeof obs.offsets.start !== 'number') {
      obs.offsets = { start: 0, end: (obs.evidence || obs.quote || '').length };
      validationErrors.push(`Observation ${i}: missing offsets, using fallback`);
    }
    if (!obs.confidence) obs.confidence = 0.7;
    if (!obs.change_type) obs.change_type = 'modified';
  }

  // Ensure summary exists
  if (!parsed.summary) {
    parsed.summary = {
      counts: { total: parsed.observations.length, missing: 0, added: 0, modified: parsed.observations.length },
      coverage_confidence: 0.7
    };
  }

  paranoidOutput = parsed;
} catch (e) {
  console.log('Paranoid parse error:', e.message);
  validationErrors.push('JSON parse error: ' + e.message);
}

return [{ json: { ...prevData, paranoidOutput, paranoidValidationErrors: validationErrors } }];

