const prevData = $('Parse Paranoid').first().json;
let valuatorOutput = { 
  decision: 'ACCEPT', 
  final_status: 'Compliant',
  needs_review: false, 
  proposed_changes: [], 
  internal_comment: '',
  client_state: 'OK',
  confidence_overall: 0.5,
  confidences: { anchor_confidence: 0.5 }
};
let validationErrors = prevData.paranoidValidationErrors || [];

try {
  const content = $json.choices?.[0]?.message?.content || '{}';
  const parsed = JSON.parse(content);

  // SCHEMA VALIDATION (Gap 2 - P1)
  const validStatuses = ['Compliant', 'AcceptableDeviation', 'UnacceptableDeviation', 'NotCoveredByPlaybook', 'Ambiguous'];
  if (!validStatuses.includes(parsed.final_status)) {
    validationErrors.push(`Invalid final_status: ${parsed.final_status}, defaulting to Ambiguous`);
    parsed.final_status = 'Ambiguous';
  }

  // Ensure proposed_changes is array
  if (!Array.isArray(parsed.proposed_changes)) {
    parsed.proposed_changes = [];
  }

  // Validate each proposed change has source_reference for no-new-text
  for (let i = 0; i < parsed.proposed_changes.length; i++) {
    const change = parsed.proposed_changes[i];
    if (!change.source_reference && change.replacement_text) {
      validationErrors.push(`Change ${i}: missing source_reference`);
      // Add placeholder source_reference
      change.source_reference = {
        source_type: 'STANDARD_POSITION',
        exact_text: change.replacement_text
      };
    }
    if (!change.anchor || !change.anchor.offsets) {
      change.anchor = {
        quote: change.original_text || '',
        offsets: { start: 0, end: 0 },
        anchor_confidence: parsed.confidences?.anchor_confidence || 0.7
      };
    }
  }

  // Ensure confidences object
  if (!parsed.confidences) {
    parsed.confidences = { anchor_confidence: 0.7 };
  }
  parsed.confidence_overall = parsed.confidence_overall || parsed.confidences.anchor_confidence || 0.7;

  valuatorOutput = parsed;
} catch (e) {
  console.log('Valuator parse error:', e.message);
  validationErrors.push('JSON parse error: ' + e.message);
  valuatorOutput.final_status = 'Ambiguous';
}

return [{ json: { ...prevData, valuatorOutput, valuatorValidationErrors: validationErrors } }];

// ValidatorDeterministic - Validates valuator output before decision
const data = $('Parse Valuator').first().json;
const errors = [];
let passed = true;

const TH_ANCHOR = data.policySpec?.decision_policy?.anchor_conf_threshold || 0.85;

// 1. Validate "No new text" - each change must have source_reference
for (const change of data.valuatorOutput?.proposed_changes || []) {
  if (change.op_type === 'INSERT' || change.op_type === 'REPLACE') {
    if (!change.source_reference?.exact_text) {
      errors.push({ 
        type: 'NO_SOURCE_REFERENCE', 
        change_id: change.change_id || 'unknown',
        message: 'Cambio sin source_reference'
      });
      passed = false;
    }
  }
}

// 2. Validate anchor confidence
let minAnchorConf = 1.0;
for (const change of data.valuatorOutput?.proposed_changes || []) {
  if (change.anchor?.anchor_confidence !== undefined) {
    minAnchorConf = Math.min(minAnchorConf, change.anchor.anchor_confidence);
  }
}

if (minAnchorConf < TH_ANCHOR && data.valuatorOutput?.proposed_changes?.length > 0) {
  errors.push({ 
    type: 'LOW_ANCHOR_CONFIDENCE', 
    min: minAnchorConf, 
    threshold: TH_ANCHOR 
  });
  // No hard fail, but recorded for potential escalation
}

// 3. Validate anchors exist in clause text
for (const change of data.valuatorOutput?.proposed_changes || []) {
  if (change.anchor?.quote && !data.clause_text.includes(change.anchor.quote)) {
    errors.push({ 
      type: 'ANCHOR_NOT_FOUND', 
      quote: change.anchor.quote.substring(0, 50) + '...'
    });
    passed = false;
  }
}

return [{
  json: {
    ...data,
    validation_passed: passed,
    validation_errors: errors,
    min_anchor_confidence: minAnchorConf,
    TH_ANCHOR: TH_ANCHOR
  }
}];

// DECISION ENGINE v2 - Priority-based thresholds + approval routing
const data = $('ValidatorDeterministic').first().json;
const valOut = data.valuatorOutput || {};
const policy = data.policySpec || {};
const family = data.routerOutput?.route || 'OtherUnknown';
const playbookSpec = data.playbookSpec || {};

// THRESHOLDS by priority
const THRESHOLDS = {
  CRITICAL: { auto: 0.95, notes: 0.85, escalate: 0.75, maxObsAuto: 0, maxObsNotes: 2 },
  HIGH: { auto: 0.92, notes: 0.82, escalate: 0.72, maxObsAuto: 1, maxObsNotes: 3 },
  MEDIUM: { auto: 0.90, notes: 0.80, escalate: 0.70, maxObsAuto: 1, maxObsNotes: 3 },
  LOW: { auto: 0.85, notes: 0.75, escalate: 0.65, maxObsAuto: 2, maxObsNotes: 5 }
};

// FAMILY PRIORITY (from 25 playbook_specs)
const FAMILY_PRIORITY = {
  PaymentCredits: 'CRITICAL', ThirdPartyCredits: 'CRITICAL', RepsProdCo: 'CRITICAL',
  IndemnityProdCo: 'CRITICAL', IndemnityAmazon: 'CRITICAL', IndemnityProcedures: 'CRITICAL',
  RightsGrant: 'CRITICAL', RightsReversion: 'CRITICAL', LiabilityLimitation: 'CRITICAL',
  InjunctiveReliefWaiver: 'CRITICAL', Assignment: 'CRITICAL', ForceMajeure: 'HIGH',
  AmazonControl: 'CRITICAL', TerminationRights: 'CRITICAL', TerminationConsequences: 'CRITICAL',
  DisputeResolution: 'HIGH', Confidentiality: 'HIGH', Insurance: 'HIGH',
  DataProtection: 'MEDIUM', ServicesScope: 'MEDIUM', PowerOfAttorney: 'MEDIUM',
  ConditionsPrecedent: 'MEDIUM', StandardTerms: 'MEDIUM', AuditRights: 'MEDIUM',
  Definitions: 'LOW', GeneralProvisions: 'LOW', Parties: 'LOW'
};

const priority = playbookSpec.priority || FAMILY_PRIORITY[family] || 'MEDIUM';
const th = THRESHOLDS[priority] || THRESHOLDS.MEDIUM;

// Gather observations
const observations = data.paranoidOutput?.observations || [];
const obsCount = observations.length;
const riskLevel = data.paranoidOutput?.risk_level || 'medium';
const finalStatus = valOut.final_status || 'Ambiguous';
const confOverall = valOut.confidence_overall || data.min_anchor_confidence || 0.7;

// Critical/passable detection
const CRITICAL_KW = ['CRITICAL', 'UNACCEPTABLE', 'REJECT', 'must reject', 'hold to form', 'unlimited liability', 'no cap'];
const PASSABLE_KW = ['compliant', 'acceptable', 'passable', 'OK to', 'NTD', 'standard'];

let hasCriticalIssue = false, hasPassableOnly = true;
for (const obs of observations) {
  const text = JSON.stringify(obs).toLowerCase();
  if (CRITICAL_KW.some(kw => text.includes(kw.toLowerCase()))) hasCriticalIssue = true;
  if (!PASSABLE_KW.some(kw => text.includes(kw.toLowerCase()))) hasPassableOnly = false;
}

// DECISION MATRIX v2
let decision = 'LOG_ONLY', escalation = { recommended: false, block_export: false, reason: '' };

// R1: Validation failed
if (!data.validation_passed && data.validation_errors?.length > 0) {
  decision = 'ESCALATE_HUMAN'; escalation = { recommended: true, block_export: true, reason: 'VALIDATION_FAILED' };
}
// R2: Unknown family
else if (family === 'OtherUnknown' || !FAMILY_PRIORITY[family]) {
  decision = 'ESCALATE_HUMAN'; escalation = { recommended: true, block_export: true, reason: 'UNKNOWN_FAMILY' };
}
// R3: Critical issue detected
else if (hasCriticalIssue) {
  decision = 'ESCALATE_HUMAN'; escalation = { recommended: true, block_export: priority === 'CRITICAL', reason: 'CRITICAL_ISSUE_DETECTED' };
}
// R4: Unacceptable in CRITICAL/HIGH
else if (finalStatus === 'UnacceptableDeviation' && (priority === 'CRITICAL' || priority === 'HIGH')) {
  decision = 'ESCALATE_HUMAN'; escalation = { recommended: true, block_export: true, reason: 'UNACCEPTABLE_DEVIATION' };
}
// R5: Compliant - AUTO APPROVE
else if (finalStatus === 'Compliant' && confOverall >= th.notes && obsCount <= th.maxObsNotes) {
  decision = 'AUTO_PASS'; escalation = { recommended: false, block_export: false, reason: 'COMPLIANT' };
}
// R6: AcceptableDeviation with confidence
else if (finalStatus === 'AcceptableDeviation' && confOverall >= th.notes && obsCount <= th.maxObsNotes) {
  decision = priority === 'CRITICAL' ? 'APPROVE_WITH_NOTES' : 'AUTO_PASS';
  escalation = { recommended: false, block_export: false, reason: 'ACCEPTABLE_DEVIATION' };
}
// R7: HIGH/MEDIUM/LOW without critical issues
else if ((priority === 'HIGH' || priority === 'MEDIUM' || priority === 'LOW') && !hasCriticalIssue && finalStatus !== 'UnacceptableDeviation') {
  decision = 'APPROVE_WITH_NOTES'; escalation = { recommended: false, block_export: false, reason: 'PASSABLE_VARIATION' };
}
// R8: CRITICAL passable
else if (priority === 'CRITICAL' && !hasCriticalIssue && (hasPassableOnly || obsCount <= 2)) {
  decision = 'APPROVE_WITH_NOTES'; escalation = { recommended: true, block_export: false, reason: 'CRITICAL_NEEDS_REVIEW' };
}
// Default
else {
  decision = 'ESCALATE_HUMAN'; escalation = { recommended: true, block_export: false, reason: 'DEFAULT_ESCALATION' };
}

// Map to client_state
const client_state = decision === 'AUTO_PASS' ? 'OK' : decision === 'APPROVE_WITH_NOTES' ? 'RECOMMENDED' : 'REQUIRED';

return [{ json: {
  ...data,
  decisorOutput: {
    decision, escalation, client_state, family_priority: priority,
    anchor_confidence: data.min_anchor_confidence || confOverall,
    confidence_overall: confOverall, observation_count: obsCount,
    has_critical_issues: hasCriticalIssue, has_passable_flag: hasPassableOnly,
    final_status: finalStatus, TH_ANCHOR: th.notes, TH_CONF: th.escalate,
    version: 'v2.0'
  }
}}];

